actions.script:
const users = {joe: 'joe.developer', bob: 'bob.developer'}
const ids = {joe: 'ORG_ZIZI_JD', bob: 'ORG_ZIZI_BD'}
const step = (name, run) => {
    ec.message.pushErrors()
    try { run(); if (ec.message.hasError()) throw new Error(ec.message.getErrorsString()) }
    catch (err) { ec.logger.error(`Report demo: ${name} not loaded: ${err && err.message ? err.message : err}`) }
    finally { ec.message.clearErrors(); ec.message.popErrors() }
}
const account = (userId) => ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().one()
if (!account(ids.joe) || !account(ids.bob)) { ec.logger.warn('The report demo needs joe.developer and bob.developer; nothing loaded'); return }
if (!ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'ACME-1').disableAuthz().one()) {
    ec.logger.warn('The report demo needs the project ACME (BossProjectsDemoData.xml); nothing loaded'); return }
if (ec.entity.find('mantle.work.time.TimeEntry').condition('workEffortId', 'ACME-1').disableAuthz().count() > 0) { ec.logger.info('The report demo is already loaded'); return }
const nowMs = Date.now()
const addDays = (text, days) => { const d = new Date(text + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + days); return d.toISOString().substring(0, 10) }
const as = (who, atMs, run) => {
    ec.user.internalLoginUser(users[who])
    ec.user.setEffectiveTime(Math.min(atMs, nowMs - 60000))
    try { return run() } finally { ec.user.setEffectiveTime(null); ec.user.logoutUser() }
}
const at = (day, hour) => Number(String(ec.l10n.parseTimestamp(day + ' ' + String(hour).padStart(2, '0') + ':00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS')))
const log = (who, day, workEffortId, fromHour, hours, comments, workTypeEnumId) => as(who, at(day, fromHour) + hours * 3600000, () => {
    ec.service.sync().name('mantle.work.TimeServices.store#TimeEntry').parameters({partyId: ids[who], workEffortId: workEffortId,
        fromDate: new Date(at(day, fromHour)), thruDate: new Date(at(day, fromHour) + hours * 3600000), hours: hours, comments: comments,
        rateTypeEnumId: 'RatpStandard', workTypeEnumId: workTypeEnumId}).call()
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
})
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const today = new Date(nowMs).toISOString().substring(0, 10)
    const js = new Date(today + 'T12:00:00Z').getUTCDay()
    const week0 = addDays(today, -((js + 6) % 7))
    const week3 = addDays(week0, -21)
    const week4 = addDays(week0, -28)
    step('Joe on ACME-1', () => [0, 1, 2, 3].forEach((i) => log('joe', addDays(week3, i), 'ACME-1', 9, 4, i < 2 ? 'Single sign-on with the Acme directory' : 'Sign-in screens and tests', 'WktpDevelopment')))
    step('Joe on ACME-3', () => { log('joe', addDays(week3, 1), 'ACME-3', 14, 3, 'The customer data import', 'WktpDevelopment'); log('joe', addDays(week3, 2), 'ACME-3', 14, 4, 'Import mapping fixes', 'WktpDevelopment') })
    step('Bob on ACME-2', () => { log('bob', addDays(week4, 2), 'ACME-2', 9, 5, 'The portal design review', 'WktpDesign'); log('bob', addDays(week4, 3), 'ACME-2', 9, 4, 'Design changes after the review', 'WktpDesign') })
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
